"""URL slugs for titles."""
import re
import unicodedata


def _words(title):
    """Return the normalized ASCII slug words for *title*."""
    text = unicodedata.normalize("NFKD", title)
    text = "".join(ch for ch in text if not unicodedata.combining(ch)).lower()
    return [word for word in re.sub(r"[^a-z0-9]+", " ", text).split()]


def slugify(title, max_length=None):
    """Lower-case ASCII words joined by hyphens, optionally shortened."""
    if max_length is not None and max_length < 1:
        raise ValueError("max_length must be at least 1")

    words = _words(title) or ["untitled"]
    if max_length is None:
        return "-".join(words)

    if len(words[0]) > max_length:
        return words[0][:max_length]

    result = words[0]
    for word in words[1:]:
        candidate = result + "-" + word
        if len(candidate) > max_length:
            break
        result = candidate
    return result


def unique_slug(title, taken, max_length=None):
    """Return a slug not present in the collection of already-used slugs."""
    base = slugify(title, max_length)
    if base not in taken:
        return base

    suffix_number = 2
    while True:
        suffix = "-" + str(suffix_number)
        if max_length is not None:
            base_limit = max_length - len(suffix)
            if base_limit < 1:
                raise ValueError("suffix leaves no room for a base slug")
            candidate = slugify(title, base_limit) + suffix
        else:
            candidate = base + suffix
        if candidate not in taken:
            return candidate
        suffix_number += 1
